 function pathCards(){return '<div class="hub-grid">'+state.home.paths.map(p=>'<article class="course-card"><div class="course-thumb">'+(p.thumbnail_url?'<img src="'+esc(p.thumbnail_url)+'" alt="">':'<i class="ti ti-route"></i>')+'</div><div class="course-body"><div class="course-name">'+esc(title(p))+'</div><p>'+esc(p.description||'')+'</p>'+progressBar(p.courseIds.length?p.completed/p.courseIds.length*100:0)+action('path-open','<i class="ti '+(p.enrolled?'ti-circle-check':'ti-route')+'"></i>'+L(p.enrolled?'ملتحق بالمسار · متابعة':'عرض دورات المسار',p.enrolled?'Enrolled · Continue path':'View path courses'),'data-id="'+esc(p.id)+'" class="'+(p.enrolled?'hub-path-enrolled':'')+'"',true)+'</div></article>').join('')+'</div>';}
 function pathAccess(p,id){const enrolled=state.home.courses.find(c=>(c.course_id||c.id)===id)?.enrolled;if(enrolled)return true;if(!p.enrolled)return false;if(p.rule==='open')return true;if(p.rule==='single')return !p.courseIds.some(cid=>cid!==id&&state.home.courses.find(c=>(c.course_id||c.id)===cid)?.enrolled&&!state.home.dashboard.courses.find(c=>c.id===cid)?.complete);return p.courseIds.slice(0,p.courseIds.indexOf(id)).every(cid=>state.home.dashboard.courses.find(c=>c.id===cid)?.complete);}
