 function courseCard(c,options={}){const policy=c._availability||{},reasons={'access-expired':L('انتهت مدة الوصول','Access expired'),ended:L('انتهت الدورة','Course ended'),upcoming:L('لم يحن موعد الإتاحة','Not available yet'),disabled:L('الالتحاق متوقف','Enrollment disabled'),full:L('اكتملت المقاعد','All seats filled'),prerequisites:L('أكمل الدورات المطلوبة أولًا','Complete prerequisite courses first')};options={...options,locked:options.locked||policy.locked,reason:options.reason||reasons[policy.reason]};const enrolled=state.home.courses.filter(c=>c.enrolled).map(c=>c.course_id||c.id),id=c.course_id||c.id,p=state.home.dashboard.courses.find(x=>x.id===id);let markup=h.renderCourseCard({...c,course_name:title(c),prerequisite:c._prerequisitesDone?'':c.prerequisite},enrolled,{...options,completed:p?.complete});const template=document.createElement('template');template.innerHTML=markup;const card=template.content.firstElementChild;card.dataset.courseTitle=title(c).toLowerCase();for(const b of card.querySelectorAll('button[onclick]')){const code=b.getAttribute('onclick');if(code.includes('enrollInCourse')){b.removeAttribute('onclick');b.dataset.hubAction='enroll-course';b.dataset.id=id;}else if(code.includes('openPlayer')){b.removeAttribute('onclick');b.dataset.hubAction='open-course';b.dataset.id=id;}}if(options.locked)card.querySelectorAll('button').forEach(b=>b.disabled=true);if(!c.enrolled&&c._request?.status==='pending'){const b=card.querySelector('button');if(b){b.outerHTML='<span class="hub-tag pending">'+L('طلب الالتحاق قيد المراجعة','Enrollment request pending')+'</span>';}}if((c.rules||c.course_rules)?.showTrainers){const note=document.createElement('p');note.className='hub-muted';note.textContent=L('المدرب: ','Trainer: ')+(c.created_by_name||c.trainer_name||c.instructor||'');card.querySelector('.course-body')?.append(note);}return card.outerHTML;}
 function pathContents(p,preview=false){return (preview?'':heading(title(p),p.description||'',action('path-back','<i class="ti ti-arrow-back-up"></i>'+L('جميع المسارات','All paths'))))+(p.enrolled?'<div class="hub-path-status"><i class="ti ti-circle-check"></i>'+L('ملتحق بالمسار','Enrolled in path')+'</div>':'<div class="hub-path-join">'+action('path-enroll','<i class="ti ti-plus"></i>'+L('التحاق بالمسار','Enroll in path'),'data-id="'+esc(p.id)+'"',true)+'</div>')+'<div class="hub-grid">'+p.courseIds.map(id=>{const c=state.home.courses.find(c=>(c.course_id||c.id)===id);if(!c)return '';const done=state.home.dashboard.courses.find(c=>c.id===id)?.complete,locked=!pathAccess(p,id);return courseCard(c,{locked,reason:!p.enrolled?L('التحق بالمسار أولًا','Enroll in the path first'):L('أكمل الدورة السابقة أولًا','Complete the previous course first'),active:!locked&&!done});}).join('')+'</div>';}

 function examCards(exams,manage){return `<div class="hub-grid">${exams.map(exam=>`<article class="hub-card"><header><h3>${esc(title(exam))}</h3><span class="hub-tag ${exam.status==='closed'?'unseen':exam.status==='open'?'done':'pending'}">${({open:L('مفتوح','Open'),closed:L('مغلق','Closed'),upcoming:L('قادم','Upcoming')})[exam.status]}</span></header><p>${L('يفتح','Opens')}: ${date(exam.startsAt)}<br>${L('يغلق','Closes')}: ${date(exam.endsAt)}</p><p>${exam.questionCount} ${L('سؤال','questions')} · ${exam.durationMinutes} ${L('دقيقة للمحاولة','minutes per attempt')}</p>${exam.attempt?.submittedAt?`<div class="hub-info">${exam.attempt.released?`${L('نتيجتك','Your score')}: ${exam.attempt.score}/${exam.attempt.total}`:L('تم التسليم؛ ستظهر النتيجة بعد إغلاق الامتحان.','Submitted; results will be released when the exam closes.')}</div>`:''}<div class="hub-actions">${manage?action('exam-edit',L('الإعدادات','Settings'),`data-id="${exam.id}"`)+action('exam-results',L('النتائج والمشاركون','Results and participants'),`data-id="${exam.id}"`)+action('exam-delete',L('حذف الامتحان','Delete examination'),`data-id="${exam.id}" class="danger"`):exam.status==='upcoming'?`<span class="hub-muted">${L('انتظر موعد الفتح','Waiting for opening time')}</span>`:action('exam-start',exam.attempt?.submittedAt?L('النتيجة والمراجعة','Results and review'):exam.attempt?L('متابعة الامتحان','Resume exam'):exam.status==='closed'?L('عرض النتيجة','View result'):L('ابدأ الامتحان','Start exam'),`data-id="${exam.id}"`,true)}</div></article>`).join('')||empty(L('لا توجد امتحانات متاحة','No examinations available'))}</div>`;}
