 function importExamQuestions(){const options=state.examOptions;const selected=[...document.querySelectorAll('[data-hub-bank-id]:checked')].map(el=>options.bank.find(q=>q.id===el.dataset.hubBankId));for(const el of document.querySelectorAll('[data-hub-bank-group]:checked'))selected.push(...(options.questionGroups.find(g=>g.id===el.dataset.hubBankGroup)?.questions||[]));for(const q of selected){if(['text','nps','scale5'].includes(q.type))continue;const optionsAr=q.type==='truefalse'?['صح','خطأ']:q.options_ar||q.options||[];state.examDraft.questions.push({id:crypto.randomUUID(),type:q.type||'choice',text:q.question_ar||q.text_ar||q.question||q.text||'',text_en:q.question_en||q.text_en||'',options:optionsAr.map(o=>typeof o==='object'?o.text_ar||o.text||o.text_en:o),options_en:q.options_en||[],correctIndex:q.type==='truefalse'&&q.correct!==undefined?(String(q.correct)==='false'?1:0):Number(q.correctIndex??q.correct_index??0)});}h.closeModal('hub-exam-bank');renderDraftQuestions();}
 async function startExam(id){const data=await api('/api/exams/'+id+'/start',{});state.examSession=data;renderExamAttempt();}
 function renderExamAttempt(keepScroll=false){const scroll=keepScroll?$('hub-exam-attempt')?.querySelector('.modal')?.scrollTop||0:0;const {exam,attempt}=state.examSession;const submitted=!!attempt.submittedAt,released=attempt.released;let body=`<div class="hub-sticky"><strong>${esc(title(exam))}</strong><span id="hub-exam-timer" class="hub-timer"></span><span>${Object.keys(attempt.answers).length}/${attempt.total} ${L('إجابة محفوظة','answers saved')}</span></div>`;
  if(submitted){body+=`<div class="hub-info">${released?`${L('النتيجة','Result')}: <strong>${attempt.score}/${attempt.total}</strong>`:L('تم تسليم الامتحان. تظهر النتيجة بعد موعد الإغلاق.','Your examination has been submitted. Results will be available after closing.')}</div>`;if(released&&!attempt.reviewEnabled)body+=`<p>${L('مراجعة الإجابات غير متاحة لهذا الامتحان.','Answer review is disabled for this examination.')}</p>`;}
  if(!submitted||attempt.reviewEnabled){const size=exam.navigationMode==='navigator'?1:exam.pageSize,page=attempt.currentPage||0,start=page*size,questions=submitted?attempt.questions:attempt.questions.slice(start,start+size);if(!submitted&&exam.navigationMode==='navigator')body+=`<nav class="hub-questions-nav">${attempt.questions.map((q,i)=>action('exam-navigate',i+1,`data-page="${i}" class="hub-question-index ${Object.hasOwn(attempt.answers,q.id)?'answered':''} ${i===page?'current':''}"`)).join('')}</nav>`;body+=questions.map((q,i)=>{const selected=attempt.answers[q.id],locked=submitted||(!exam.allowAnswerChange&&Object.hasOwn(attempt.answers,q.id));return `<fieldset class="hub-question"><legend>${submitted?i+1:start+i+1}. ${esc(h.language()==='en'?q.text_en||q.text:q.text)}</legend>${q.options.map((option,index)=>`<label class="hub-answer ${selected===index?'selected':''} ${submitted?(q.correctIndex===index?'correct':selected===index?'wrong':''):''}"><input type="radio" name="hub-answer-${q.id}" data-hub-answer="${esc(q.id)}" value="${index}" ${selected===index?'checked':''} ${locked?'disabled':''}><span>${esc(h.language()==='en'?q.options_en?.[index]||option:option)}</span>${submitted&&q.correctIndex===index?' ✓':''}</label>`).join('')}</fieldset>`;}).join('');if(!submitted){const pages=Math.ceil(attempt.questions.length/size);body+=`<div class="hub-actions">${page>0&&!exam.lockPassedPages?action('exam-navigate',L('السابق','Previous'),`data-page="${page-1}"`):''}${page<pages-1?action('exam-navigate',L('التالي','Next'),`data-page="${page+1}"`):''}${action('exam-submit',L('تسليم نهائي','Submit examination'),'',true)}</div>`;}}
  modal('hub-exam-attempt',L('الامتحان','Examination'),body).querySelector('.modal').scrollTop=scroll;clearInterval(examTimer);if(!submitted){const tick=()=>{const left=Math.max(0,attempt.deadlineAt-Date.now());if($('hub-exam-timer'))$('hub-exam-timer').textContent=`${Math.floor(left/60000)}:${String(Math.floor(left/1000)%60).padStart(2,'0')}`;if(left<=0){clearInterval(examTimer);refreshAttempt().catch(e=>h.toast(e.message,'error'));}};tick();examTimer=setInterval(tick,1000);}else{if($('hub-exam-timer'))$('hub-exam-timer').textContent=L('تم التسليم','Submitted');if(!released)examTimer=setInterval(()=>{if(Date.now()>=exam.endsAt){clearInterval(examTimer);refreshAttempt().catch(e=>h.toast(e.message,'error'));}},1000);else examTimer=setInterval(()=>{if($('hub-exam-attempt')?.classList.contains('hidden'))return clearInterval(examTimer);refreshAttempt().catch(e=>h.toast(e.message,'error'));},5000);}
 }
 async function refreshAttempt(){state.examSession=await api('/api/exams/'+state.examSession.exam.id+'/attempt');renderExamAttempt(true);}
 async function examResults(id){const data=await api('/api/exams/'+id+'/results');state.examResults=data;modal('hub-exam-results',L('نتائج الامتحان','Examination results'),heading(title(data.exam),L('إتاحة المراجعة لكل متدرب بعد الإغلاق، مع احترام إعداد المراجعة العام للامتحان.','Individual review is released after closure and requires the examination review setting.'),action('exam-results-excel','Excel'))+table([L('المتدرب','Learner'),L('الرقم الوظيفي','Employee ID'),L('الحالة','Status'),L('الدرجة','Score'),L('إتاحة مراجعة الإجابات','Allow answer review')],data.results.map(r=>[esc(r.person.full_name),esc(r.person.employee_id),r.attempt?(r.attempt.submittedAt?L('تم التسليم','Submitted'):L('جارٍ الحل','In progress')):L('لم يبدأ','Not started'),r.attempt?.submittedAt?r.attempt.score+'/'+r.attempt.total:'—',r.attempt?.submittedAt?'<label class="hub-check"><input type="checkbox" '+(Date.now()<data.exam.endsAt?'disabled ':'')+'data-hub-review="'+esc(id)+'" data-email="'+esc(r.person.email)+'" '+(r.attempt.reviewAllowed!==false?'checked':'')+'>'+L('إتاحة','Allow')+'</label>':'—'])));}
 function openPeoplePicker(kind){state.peoplePickerKind=kind;state.peoplePickerSelection=new Set(kind==='exam'?state.examDraft.assignedEmails:h.pathSelection());state.peoplePickerRows=kind==='exam'?state.examOptions.people:h.people().filter(u=>u.role==='trainee'&&u.status!=='deleted');modal('hub-people-picker',L('اختيار المتدربين','Select learners'),'<input data-hub-input="people-picker-search" id="hub-people-picker-search" placeholder="'+esc(L('البحث بالاسم أو الرقم الوظيفي','Search name or employee ID'))+'"><div id="hub-people-picker-list" class="hub-pick-list"></div><div id="hub-people-picker-count"></div>'+action('people-picker-save',L('إضافة المحدد وإغلاق','Add selected and close'),'',true));renderPeoplePicker();}
