 function enhancePathEditor(){const box=$('lp-user-picker');if(!box)return;if(!$('hub-path-import-tools'))box.insertAdjacentHTML('beforebegin',`<div id="hub-path-import-tools" class="hub no-i18n"><div class="hub-actions">${action('people-template',L('تحميل نموذج Excel','Download Excel template'))}<label>${L('استيراد متدربين','Import learners')}<input class="hub-file" type="file" accept=".xlsx,.csv" data-hub-file="path-draft-people"></label></div><input id="hub-path-member-search" data-hub-input="path-draft-search" placeholder="${esc(L('بحث بالاسم أو الرقم الوظيفي','Search name or employee ID'))}"><div class="hub-picked" id="hub-path-selected"></div>${action('people-picker',L('إضافة أسماء','Add people'),'data-kind="path"')}<div id="hub-path-import-status"></div></div>`);renderPathDraftPeople();$('lp-user-picker').hidden=true;$('hub-path-member-search').hidden=true;}
