 function personReport(scope='all'){let d=state.person||state.home?.dashboard;if(d&&scope!=='all'){const courses=scope==='certificates'?[]:d.courses.filter(c=>scope==='certificate'?c.hasCertificate:!c.hasCertificate),ids=new Set(courses.map(c=>c.id)),certificates=scope==='certificates'?d.certificates:d.certificates.filter(c=>ids.has(c.courseId||c.course_id));d={...d,courses,certificates,summary:{...d.summary,enrolled:courses.length,certificates:certificates.length}};}if(!d)throw Error(L('افتح لوحة المتدرب أولًا','Open a learner dashboard first'));return {scope,title:scope==='all'?L('تقرير إنجاز المتدرب المجمع','Combined learner achievement report'):scope==='certificate'?L('تقرير الدورات بشهادات','Certificate course report'):scope==='no-certificate'?L('تقرير الدورات دون شهادات','Non-certificate course report'):L('تقرير الشهادات المكتسبة','Earned certificates report'),subtitle:`${d.person.full_name} · ${d.person.employee_id||d.person.email}`,metrics:[...[true,false].filter(flag=>scope==='all'||scope==='certificate'&&flag||scope==='no-certificate'&&!flag).map(flag=>{const rows=d.courses.filter(c=>c.hasCertificate===flag);return [pct(rows.length?Math.round(rows.filter(c=>c.complete).length/rows.length*100):0),flag?L('إنجاز الدورات بشهادات','Certificate course completion'):L('إنجاز الدورات دون شهادات','Non-certificate course completion')];}),[d.summary.certificates,L('شهادات مكتسبة','Certificates earned')]],sections:[{title:L('الدورات','Courses'),headers:[L('الدورة','Course'),L('تقدم المحتوى','Content progress'),L('الاكتمال','Completed'),L('الشهادة','Certificate')],rows:d.courses.map(c=>[title(c),pct(c.percent),c.complete?L('مكتملة','Complete'):L('غير مكتملة','Incomplete'),c.hasCertificate?L('بشهادة','With certificate'):L('دون شهادة','Without certificate')])},{title:L('تفاصيل المحتوى','Content details'),headers:[L('الدورة','Course'),L('المحتوى','Content'),L('النوع','Type'),L('التقدم','Progress'),L('المحاولات والدرجات','Attempts and scores')],rows:d.courses.flatMap(c=>c.items.map(v=>[title(c),h.language()==='en'?v.title_en:v.title,typeName(v.type),v.completed?'✓ 100%':v.started?pct(v.percent):L('لم يبدأ','Not started'),v.attempts.map(a=>`${a.attemptNo||''}: ${a.score}/${a.total}`).join(' | ')]))},{title:L('الشهادات','Certificates'),headers:[L('الشهادة','Certificate'),L('تاريخ الإصدار','Issued on')],rows:d.certificates.map(c=>[c.course_name||c.courseId,date(c.issued_at||c.createdAt)])}]};}
 function regionReport(){const d=state.regions;if(!d)throw Error('No report');return {title:L('تقرير الأقاليم','Regional report'),subtitle:`${d.category==='certificate'?L('دورات بشهادات','Certificate courses'):d.category==='no-certificate'?L('دورات دون شهادات','Non-certificate courses'):L('جميع الدورات','All courses')} · ${L('المستهدف','Target')}: ${d.target}% · ${L('دورات مستبعدة','Excluded courses')}: ${d.excludeCourses.length}`,metrics:[[d.summary.learners,L('متدربون','Learners')],[pct(d.summary.percent),L('الإنجاز','Completion')],[d.summary.remainingToTarget,L('المتبقي للمستهدف','Remaining to target')]],sections:[{title:L('الأقاليم','Regions'),headers:[L('الإقليم','Region'),L('المتدربون','Learners'),L('الدورات','Courses'),L('الإنجاز','Completion'),L('المتبقي','Remaining')],rows:d.regions.map(r=>[r.region,r.learners,r.courseCount,pct(r.percent),r.remainingToTarget])},{title:L('تقدم الدورات','Course progress'),headers:[L('الإقليم','Region'),L('الدورة','Course'),L('المسجلون','Enrolled'),L('المكتملون','Completed'),L('الإنجاز','Completion'),L('المتبقي','Remaining')],rows:d.regions.flatMap(r=>r.courses.map(c=>[r.region,title(c),c.learners,c.completed,pct(c.percent),c.remainingToTarget]))},{title:L('المشرفون','Supervisors'),headers:[L('الإقليم','Region'),L('المشرف','Supervisor'),L('المتدربون','Learners'),L('الالتحاقات','Enrollments'),L('الإنجاز','Completion'),L('المتبقي','Remaining')],rows:d.regions.flatMap(r=>r.supervisors.map(s=>[r.region,s.name,s.learners,s.enrollments,pct(s.percent),s.remainingToTarget]))}]};}
 function reportExcel(report,filename){const wb=XLSX.utils.book_new(),used=new Set();const append=(title,data)=>{const base=String(title||L('بيانات','Data')).replace(/[\\/?*\[\]:]/g,' ').trim()||'Data';let name=base.slice(0,31),n=1;while(used.has(name.toLowerCase())){const suffix=' ('+(++n)+')';name=base.slice(0,31-suffix.length)+suffix;}used.add(name.toLowerCase());XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet(data),name);};append(L('ملخص التقرير','Report summary'),[[report.title],[report.subtitle||''],[],[L('المؤشر','Metric'),L('القيمة','Value')],...(report.metrics||[]).map(([v,label])=>[label,v])]);for(const section of report.sections)append(section.title,[section.headers,...section.rows]);XLSX.writeFile(wb,filename);}
 let pdfLibraries=null;
 function script(src){return new Promise((resolve,reject)=>{const el=document.createElement('script');el.src=src;el.onload=resolve;el.onerror=()=>reject(Error(L('تعذر تحميل أدوات PDF','Unable to load PDF tools')));document.head.append(el);});}
 async function reportPDF(report,filename){
  pdfLibraries||=Promise.all([script('/vendor/html2canvas.min.js'),script('/vendor/jspdf.min.js')]);await pdfLibraries;await document.fonts.ready;
  const host=document.createElement('div');host.className='hub-print-host no-i18n';document.body.append(host);const pages=[];let paper;
  const newPage=(first=false)=>{paper=document.createElement('div');paper.className='hub hub-report-paper';paper.dir=h.language()==='en'?'ltr':'rtl';paper.innerHTML=`<header class="hub-report-mast"><h1>${esc(report.title)}</h1><div class="hub-report-meta">${esc(report.subtitle||'')}<br>${esc(date(Date.now()))}</div></header>${first?`<div class="hub-stats">${(report.metrics||[]).map(([value,label])=>stat(value,label)).join('')}</div>`:''}${first?(report.chart||''):''}`;host.append(paper);pages.push(paper);};newPage(true);
  for(const block of report.visualBlocks||[]){const element=document.createElement('section');element.className='hub-report-visual';element.innerHTML=block;paper.append(element);if(element.getBoundingClientRect().bottom-paper.getBoundingClientRect().top>1380){element.remove();newPage();paper.append(element);}}
  for(const section of report.sections){if(!section.rows.length)continue;let tableElement,tbody;
   const sectionHeader=()=>{const heading=document.createElement('h2');heading.textContent=section.title;paper.append(heading);tableElement=document.createElement('table');tableElement.innerHTML=`${section.widths?'<colgroup>'+section.widths.map(w=>'<col style="width:'+w+'%">').join('')+'</colgroup>':''}<thead><tr>${section.headers.map(s=>`<th>${esc(s)}</th>`).join('')}</tr></thead><tbody></tbody>`;paper.append(tableElement);tbody=tableElement.querySelector('tbody');};
   sectionHeader();const expanded=section.rows.flatMap(values=>{const parts=values.map(value=>String(value??'').match(/[\s\S]{1,200}/g)||['']);return Array.from({length:Math.max(...parts.map(x=>x.length))},(_,i)=>parts.map(x=>x[i]||''));});
   for(const values of expanded){const row=document.createElement('tr');row.innerHTML=values.map(v=>`<td>${esc(v)}</td>`).join('');tbody.append(row);if(row.getBoundingClientRect().bottom-paper.getBoundingClientRect().top>1410){row.remove();if(!tbody.children.length){tableElement.previousElementSibling?.remove();tableElement.remove();}newPage();sectionHeader();tbody.append(row);}}
  }
  try{const doc=new window.jspdf.jsPDF({unit:'mm',format:'a4',compress:true});for(let i=0;i<pages.length;i++){const footer=document.createElement('div');footer.className='hub-report-footer';footer.textContent=`${L('أكاديمية التدريب','Training Academy')} · ${i+1} / ${pages.length}`;pages[i].append(footer);const canvas=await window.html2canvas(pages[i],{scale:1.5,backgroundColor:'#ffffff',logging:false});if(i)doc.addPage();doc.addImage(canvas.toDataURL('image/jpeg',.94),'JPEG',0,0,210,297);pages[i].remove();}doc.save(filename);}finally{host.remove();}
 }

